"""Print the numbers the manuscript quotes, as markdown tables, and save them to results/tables.md.

Run:  python code/06_tables.py
"""
import sys
from pathlib import Path

import pandas as pd

sys.stdout.reconfigure(encoding="utf-8")
RES = Path(__file__).resolve().parents[1] / "results"
res = pd.read_csv(RES / "experiment_results.csv")
det = pd.read_csv(RES / "detection_results.csv")
on = pd.read_csv(RES / "onsets.csv")
# OKF frontmatter so the generated file is a valid concept in the bundle
out = ["---\ntype: results\ntitle: Paper B result tables\n"
       "description: Every number quoted in the Paper B draft, generated by code/06_tables.py.\n"
       "generated: {by: process:code/06_tables.py}\n---\n"]

out.append("## Table: onsets\n")
out.append(on[["file", "onset_t", "score_vs_F0", "feat_score_vs_F0", "top_feature", "locatable"]]
           .round(2).to_markdown(index=False))

out.append("\n\n## Table: protocol summary (macro-F1 mean ± sd over 5 seeds)\n")
g = res.groupby(["exp", "scope", "features", "model"])["macro_f1"].agg(["mean", "std"]).reset_index()
g["macro_f1"] = g["mean"].map("{:.3f}".format) + " ± " + g["std"].map("{:.3f}".format)
out.append(g.drop(columns=["mean", "std"]).to_markdown(index=False))

out.append("\n\n## Table: cross-mode, seed 0, with block-bootstrap 95% CI and per-class recall\n")
cm = res[(res.exp == "E3b_cross_mode") & (res.seed == 0)]
cols = ["scope", "features", "model", "macro_f1", "f1_ci_lo", "f1_ci_hi", "bal_acc"] + \
       [c for c in res.columns if c.startswith("recall_F")]
out.append(cm[cols].round(3).to_markdown(index=False))

out.append("\n\n## Table: detection\n")
out.append(det[["detector", "file", "fault", "onset_t", "detected", "delay_s", "false_alarm_rate_pre",
                "post_alarm_fraction"]].round(3).to_markdown(index=False))

out.append("\n\n## E3 class counts\n")
text = "\n".join(out)
(RES / "tables.md").write_text(text, encoding="utf-8")
print(text)
